<h1 class="fw-bold mb-4">Quản lý sản phẩm</h1><div class="card card-body mb-4"><h5>Thêm sản phẩm</h5><form method="post" action="/admin/products/create" class="row g-2"><div class="col-md-4"><input class="form-control" name="name" placeholder="Tên điện thoại" required></div><div class="col-md-2"><input class="form-control" type="number" min="1" name="price" placeholder="Giá" required></div><div class="col-md-2"><input class="form-control" type="number" min="0" name="stock" placeholder="Tồn kho" required></div><div class="col-md-4"><input class="form-control" name="image" placeholder="URL ảnh"></div><div class="col-12"><textarea class="form-control" name="description" placeholder="Mô tả"></textarea></div><div class="col-12"><button class="btn btn-warning">Thêm sản phẩm</button></div></form></div>
